Plan: Keep closure in the queue monitor rather than encoding it as an item.

```c
#define _XOPEN_SOURCE 700
#include <pthread.h>
#include <semaphore.h>
#include <stdio.h>
#include <stdlib.h>
#include <assert.h>
#include <errno.h>
#include <time.h>
#include <string.h>
#include <stdbool.h>
#include <stdint.h>
#include <limits.h>
#include <sched.h>
#include <signal.h>
#include <stdatomic.h>
static void ck(int e) { if (e) { fprintf(stderr,"pthread error %d\n",e); exit(1); } }
#define SO(x) do { if ((x)==-1) { perror(#x); exit(1); } } while (0)
#define P(s) do { int e; do { e=sem_wait(&(s)); } while (e==-1 && errno==EINTR); if (e==-1) { perror("sem_wait"); exit(1); } } while (0)
#define V(s) SO(sem_post(&(s)))
static pthread_mutex_t m=PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t ne=PTHREAD_COND_INITIALIZER,nf=PTHREAD_COND_INITIALIZER;
static int q[2],head,tail,count,closed,delivered,ids[3]={0,1,2};
static void *producer(void *p) {
    int id=*(int *)p;
    for(int j=0;j<2;j++) {
        ck(pthread_mutex_lock(&m));
        while(count==2) ck(pthread_cond_wait(&nf,&m));
        q[tail]=id*2+j; tail=(tail+1)%2; ++count;
        ck(pthread_cond_signal(&ne)); ck(pthread_mutex_unlock(&m));
    } return NULL;
}
static void *consumer(void *p) {
    (void)p;
    for(int j=0;j<=6;j++) {
        ck(pthread_mutex_lock(&m));
        while(count==0 && !closed) ck(pthread_cond_wait(&ne,&m));
        if(count==0) { ck(pthread_mutex_unlock(&m)); return NULL; }
        assert(q[head]>=0); head=(head+1)%2; --count; ++delivered;
        ck(pthread_cond_signal(&nf)); ck(pthread_mutex_unlock(&m));
    } abort();
}
int main(void) {
    pthread_t p[3],c[2];
    for(int i=0;i<2;i++) ck(pthread_create(&c[i],NULL,consumer,NULL));
    for(int i=0;i<3;i++) ck(pthread_create(&p[i],NULL,producer,&ids[i]));
    for(int i=0;i<3;i++) ck(pthread_join(p[i],NULL));
    ck(pthread_mutex_lock(&m)); closed=1; ck(pthread_cond_broadcast(&ne));
    ck(pthread_mutex_unlock(&m));
    for(int i=0;i<2;i++) ck(pthread_join(c[i],NULL));
    assert(count==0 && delivered==6);
    ck(pthread_cond_destroy(&ne)); ck(pthread_cond_destroy(&nf));
    ck(pthread_mutex_destroy(&m)); puts("orders drained after closure"); return 0;
}
```

Why it is correct: All predicates and queue operations use m. Each wait releases m atomically and rechecks in a while loop. Closure broadcasts to all consumers, and empty plus closed is the exit predicate; pending orders are not discarded.

