Plan: Serialize sorted insertion and close the submission phase with joins before printing.

```c
#define _XOPEN_SOURCE 700
#include <pthread.h>
#include <semaphore.h>
#include <stdio.h>
#include <stdlib.h>
#include <assert.h>
#include <errno.h>
#include <time.h>
#include <string.h>
#include <stdbool.h>
#include <stdint.h>
#include <limits.h>
#include <sched.h>
#include <signal.h>
#include <stdatomic.h>
static void ck(int e) { if (e) { fprintf(stderr,"pthread error %d\n",e); exit(1); } }
#define SO(x) do { if ((x)==-1) { perror(#x); exit(1); } } while (0)
#define P(s) do { int e; do { e=sem_wait(&(s)); } while (e==-1 && errno==EINTR); if (e==-1) { perror("sem_wait"); exit(1); } } while (0)
#define V(s) SO(sem_post(&(s)))
typedef struct Node { int priority; struct Node *next; } Node;
static pthread_mutex_t m=PTHREAD_MUTEX_INITIALIZER;
static Node *head;
static int priority[4]={2,4,1,3},printed[4];
static void *submit(void *p) {
    Node *n=malloc(sizeof *n); assert(n); n->priority=*(int *)p;
    ck(pthread_mutex_lock(&m)); Node **link=&head;
    while(*link && (*link)->priority>n->priority) link=&(*link)->next;
    n->next=*link; *link=n; ck(pthread_mutex_unlock(&m)); return NULL;
}
static void *printer(void *p) {
    (void)p;
    for(int i=0;i<4;i++) {
        ck(pthread_mutex_lock(&m)); Node *n=head; assert(n); head=n->next;
        ck(pthread_mutex_unlock(&m)); printed[i]=n->priority; free(n);
    } return NULL;
}
int main(void) {
    pthread_t s[4],p; for(int i=0;i<4;i++) ck(pthread_create(&s[i],NULL,submit,&priority[i]));
    for(int i=0;i<4;i++) ck(pthread_join(s[i],NULL));
    ck(pthread_create(&p,NULL,printer,NULL)); ck(pthread_join(p,NULL));
    for(int i=0;i<4;i++) assert(printed[i]==4-i);
    assert(!head); ck(pthread_mutex_destroy(&m)); return 0;
}
```

Why it is correct: Insertion preserves list order under m. The printer detaches each node before freeing it, and submitters have already finished, so lifetime and final priority order are well-defined. The batch barrier avoids claiming future arrivals can be printed in advance.

