Plan: Transfer exclusive ownership of each batch buffer at the ready/free handoff.

```c
#define _XOPEN_SOURCE 700
#include <pthread.h>
#include <semaphore.h>
#include <stdio.h>
#include <stdlib.h>
#include <assert.h>
#include <errno.h>
#include <time.h>
#include <string.h>
#include <stdbool.h>
#include <stdint.h>
#include <limits.h>
#include <sched.h>
#include <signal.h>
#include <stdatomic.h>
static void ck(int e) { if (e) { fprintf(stderr,"pthread error %d\n",e); exit(1); } }
#define SO(x) do { if ((x)==-1) { perror(#x); exit(1); } } while (0)
#define P(s) do { int e; do { e=sem_wait(&(s)); } while (e==-1 && errno==EINTR); if (e==-1) { perror("sem_wait"); exit(1); } } while (0)
#define V(s) SO(sem_post(&(s)))
static sem_t free_slot[2],ready[2];
static int batch[2][3],sum;
static void *format(void *p) {
    (void)p;
    for(int b=0;b<4;b++) {
        int slot=b%2; P(free_slot[slot]);
        for(int j=0;j<3;j++) batch[slot][j]=3*b+j+1;
        V(ready[slot]);
    } return NULL;
}
static void *write_batch(void *p) {
    (void)p;
    for(int b=0;b<4;b++) {
        int slot=b%2; P(ready[slot]);
        for(int j=0;j<3;j++) { assert(batch[slot][j]==3*b+j+1); sum+=batch[slot][j]; }
        V(free_slot[slot]);
    } return NULL;
}
int main(void) {
    pthread_t f,w;
    for(int i=0;i<2;i++) { SO(sem_init(&free_slot[i],0,1)); SO(sem_init(&ready[i],0,0)); }
    ck(pthread_create(&w,NULL,write_batch,NULL)); ck(pthread_create(&f,NULL,format,NULL));
    ck(pthread_join(f,NULL)); ck(pthread_join(w,NULL)); assert(sum==78);
    for(int i=0;i<2;i++) { SO(sem_destroy(&free_slot[i])); SO(sem_destroy(&ready[i])); }
    return 0;
}
```

Why it is correct: The formatter waits for free before overwriting; the writer waits for ready before reading and returns free only after the whole batch. Each slot has one owner at a time, and semaphore publication orders its contents. Fixed batch counts avoid shutdown ambiguity.

