Plan: Use one absolute deadline, recheck the predicate under m, and execute the exit section even on timeout.

```c
#define _XOPEN_SOURCE 700
#include <pthread.h>
#include <semaphore.h>
#include <stdio.h>
#include <stdlib.h>
#include <assert.h>
#include <errno.h>
#include <time.h>
#include <string.h>
#include <stdbool.h>
#include <stdint.h>
#include <limits.h>
#include <sched.h>
#include <signal.h>
#include <stdatomic.h>
static void ck(int e) { if (e) { fprintf(stderr,"pthread error %d\n",e); exit(1); } }
#define SO(x) do { if ((x)==-1) { perror(#x); exit(1); } } while (0)
#define P(s) do { int e; do { e=sem_wait(&(s)); } while (e==-1 && errno==EINTR); if (e==-1) { perror("sem_wait"); exit(1); } } while (0)
#define V(s) SO(sem_post(&(s)))
static pthread_mutex_t m=PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t cv=PTHREAD_COND_INITIALIZER;
static int ready,item,timed_out;
static void *receive(void *p) {
    (void)p; struct timespec deadline; SO(clock_gettime(CLOCK_REALTIME,&deadline));
    deadline.tv_nsec+=1000000; if(deadline.tv_nsec>=1000000000) { ++deadline.tv_sec; deadline.tv_nsec-=1000000000; }
    ck(pthread_mutex_lock(&m));
    while(!ready) {
        int e=pthread_cond_timedwait(&cv,&m,&deadline);
        if(e==ETIMEDOUT && !ready) { timed_out=1; break; }
        if(e!=ETIMEDOUT) ck(e);
    }
    ck(pthread_mutex_unlock(&m)); return NULL;
}
int main(void) {
    pthread_t t; ck(pthread_create(&t,NULL,receive,NULL)); ck(pthread_join(t,NULL));
    ck(pthread_mutex_lock(&m)); assert(timed_out); item=9; ready=1; ck(pthread_mutex_unlock(&m));
    assert(item==9); ck(pthread_cond_destroy(&cv)); ck(pthread_mutex_destroy(&m)); return 0;
}
```

Why it is correct: A normal timed wait reacquires m before returning, including ETIMEDOUT. The receiver explicitly unlocks after leaving its while loop. Main joins before the late insertion, so the example checks timeout cleanup without racing or pretending a timeout proves a concurrent predicate is false.

